package main

import "testing"

// TestDeriveSeriesName drives the plugin-local title+season derivation over
// the directory-name shapes a serial record's raw facts carry: the season
// markers (word, ordinal, Sxx, TV), the roman sequel, the bracket rule, the
// trailing group tag, the file-backed extension, and the always-season
// adapter default. Every expectation mirrors what plugins/serial-parser's
// parseSeriesDir derives from the same input.
func TestDeriveSeriesName(t *testing.T) {
	tests := []struct {
		name   string
		raw    string
		title  string
		season int64
	}{
		{"plain directory name defaults to season 1", "Cowboy Bebop", "Cowboy Bebop", 1},
		{"Sxx marker cuts and sets the season", "Cowboy Bebop S01", "Cowboy Bebop", 1},
		{"a higher marker value wins", "Frieren S02", "Frieren", 2},
		{"cyrillic titles are preserved", "Ковбой Бибоп S01", "Ковбой Бибоп", 1},
		{"word-form marker", "Show Season 3", "Show", 3},
		{"ordinal marker", "Show 4th Season", "Show", 4},
		{"TV marker", "Show TV 2", "Show", 2},
		{"trailing roman sequel sets the season", "Show II", "Show", 2},
		{"leading group bracket strips", "[HorribleSubs] Show S01", "Show", 1},
		{"a release-decoration bracket strips", "Show (1080p) S01", "Show", 1},
		{"a year bracket strips", "Show (2023) S01", "Show", 1},
		{"a title-bearing bracket is preserved", "Show_(Shiro)_S01", "Show (Shiro)", 1},
		{"a trailing group tag cuts", "Show - FanSub", "Show", 1},
		{"a file-backed name drops its extension", "Show S01.mkv", "Show", 1},
		{"an SxxExx token is not a season marker", "Show S01E01", "Show S01E01", 1},
		{"separators normalize to spaces", "Show.Name.S01", "Show Name", 1},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			title, season := deriveSeriesName(tc.raw)
			if title != tc.title || season != tc.season {
				t.Fatalf("deriveSeriesName(%q) = (%q, %d), want (%q, %d)",
					tc.raw, title, season, tc.title, tc.season)
			}
		})
	}
}
